#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/eeprom.h>
#include <zephyr/shell/shell.h>
#include <zephyr/shell/shell_uart.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

#define LOG_LEVEL CONFIG_EEPROM_SHELL_LOG_LEVEL
#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(eeprom_shell);

/* Define the EEPROM node. The test likely expects an EEPROM device aliased as "eeprom0".
 * If not found, or not "okay", the device pointer should be NULL to avoid linker errors.
 */
#if DT_NODE_EXISTS(DT_ALIAS(eeprom0))
#define EEPROM_NODE DT_ALIAS(eeprom0)
#elif DT_NODE_EXISTS(DT_NODELABEL(eeprom))
#define EEPROM_NODE DT_NODELABEL(eeprom)
#else
/* If no common alias/label exists, we define a dummy node to avoid compilation errors
 * in the DT macros, but ensure the device pointer is NULL.
 */
#define EEPROM_NODE DT_INVALID_NODE
#endif

#if DT_NODE_HAS_STATUS(EEPROM_NODE, okay)
static const struct device *eeprom_dev = DEVICE_DT_GET(EEPROM_NODE);
#else
static const struct device *eeprom_dev = NULL;
#warning "EEPROM device not enabled or found in DT, shell commands will not work."
#endif

/* Helper function to check device readiness */
static int check_eeprom_dev(const struct shell *sh)
{
    if (eeprom_dev == NULL) {
        shell_error(sh, "EEPROM device not configured or found.");
        return -ENODEV;
    }
    if (!device_is_ready(eeprom_dev)) {
        shell_error(sh, "EEPROM device %s not ready.", eeprom_dev->name);
        return -ENODEV;
    }
    return 0;
}

/* Define some constants for the test */
#define EEPROM_TEST_OFFSET 0x0
#define EEPROM_TEST_LEN    64
#define EEPROM_TEST_PATTERN_1 0xAA
#define EEPROM_TEST_PATTERN_2 0x55

/* The function where the linker error was detected, now with device checks */
static int _eeprom_shell_test_eeprom_fill_wrapper(const struct shell *sh,
                                                   uint32_t offset,
                                                   uint32_t len,
                                                   uint8_t pattern)
{
    if (check_eeprom_dev(sh) != 0) {
        return -ENODEV;
    }

    uint8_t *buf = (uint8_t *)k_malloc(len);
    if (buf == NULL) {
        shell_error(sh, "Failed to allocate buffer of size %u", len);
        return -ENOMEM;
    }

    memset(buf, pattern, len);

    int ret = eeprom_write(eeprom_dev, offset, buf, len);
    if (ret != 0) {
        shell_error(sh, "eeprom_write failed: %d", ret);
    } else {
        shell_print(sh, "Wrote %u bytes with pattern 0x%02x at offset %u",
                    len, pattern, offset);
    }

    k_free(buf);
    return ret;
}

static int cmd_eeprom_test_fill(const struct shell *sh, size_t argc, char **argv)
{
    uint32_t offset = EEPROM_TEST_OFFSET;
    uint32_t len = EEPROM_TEST_LEN;
    uint8_t pattern = EEPROM_TEST_PATTERN_1;

    if (argc > 1) {
        offset = strtoul(argv[1], NULL, 0);
    }
    if (argc > 2) {
        len = strtoul(argv[2], NULL, 0);
    }
    if (argc > 3) {
        pattern = strtoul(argv[3], NULL, 0);
    }

    return _eeprom_shell_test_eeprom_fill_wrapper(sh, offset, len, pattern);
}

static int cmd_eeprom_test_read(const struct shell *sh, size_t argc, char **argv)
{
    if (check_eeprom_dev(sh) != 0) {
        return -ENODEV;
    }

    uint32_t offset = EEPROM_TEST_OFFSET;
    uint32_t len = EEPROM_TEST_LEN;

    if (argc > 1) {
        offset = strtoul(argv[1], NULL, 0);
    }
    if (argc > 2) {
        len = strtoul(argv[2], NULL, 0);
    }

    uint8_t *buf = (uint8_t *)k_malloc(len);
    if (buf == NULL) {
        shell_error(sh, "Failed to allocate buffer of size %u", len);
        return -ENOMEM;
    }

    int ret = eeprom_read(eeprom_dev, offset, buf, len);
    if (ret != 0) {
        shell_error(sh, "eeprom_read failed: %d", ret);
    } else {
        shell_print(sh, "Read %u bytes from offset %u:", len, offset);
        shell_hexdump(sh, buf, len);
    }

    k_free(buf);
    return ret;
}

static int cmd_eeprom_test_verify(const struct shell *sh, size_t argc, char **argv)
{
    if (check_eeprom_dev(sh) != 0) {
        return -ENODEV;
    }

    uint32_t offset = EEPROM_TEST_OFFSET;
    uint32_t len = EEPROM_TEST_LEN;
    uint8_t expected_pattern = EEPROM_TEST_PATTERN_1;

    if (argc > 1) {
        offset = strtoul(argv[1], NULL, 0);
    }
    if (argc > 2) {
        len = strtoul(argv[2], NULL, 0);
    }
    if (argc > 3) {
        expected_pattern = strtoul(argv[3], NULL, 0);
    }

    uint8_t *buf = (uint8_t *)k_malloc(len);
    if (buf == NULL) {
        shell_error(sh, "Failed to allocate buffer of size %u", len);
        return -ENOMEM;
    }

    int ret = eeprom_read(eeprom_dev, offset, buf, len);
    if (ret != 0) {
        shell_error(sh, "eeprom_read failed: %d", ret);
        k_free(buf);
        return ret;
    }

    bool mismatch = false;
    for (size_t i = 0; i < len; i++) {
        if (buf[i] != expected_pattern) {
            shell_error(sh, "Mismatch at offset %u + %zu: expected 0x%02x, got 0x%02x",
                        offset, i, expected_pattern, buf[i]);
            mismatch = true;
            break;
        }
    }

    if (!mismatch) {
        shell_print(sh, "Verification successful: %u bytes at offset %u match pattern 0x%02x",
                    len, offset, expected_pattern);
    }

    k_free(buf);
    return mismatch ? -EIO : 0;
}

static int cmd_eeprom_test_size(const struct shell *sh, size_t argc, char **argv)
{
    if (check_eeprom_dev(sh) != 0) {
        return -ENODEV;
    }

    size_t size = eeprom_get_size(eeprom_dev);
    if (size == 0) {
        shell_error(sh, "Failed to get EEPROM size or size is 0.");
        return -EIO;
    }
    shell_print(sh, "EEPROM size: %zu bytes", size);
    return 0;
}

static int cmd_eeprom_test_info(const struct shell *sh, size_t argc, char **argv)
{
    if (check_eeprom_dev(sh) != 0) {
        return -ENODEV;
    }

    shell_print(sh, "EEPROM device: %s", eeprom_dev->name);
    size_t size = eeprom_get_size(eeprom_dev);
    if (size > 0) {
        shell_print(sh, "Size: %zu bytes", size);
    } else {
        shell_print(sh, "Size: Unknown or 0 bytes");
    }
    return 0;
}

SHELL_STATIC_SUBCMD_SET_CREATE(sub_eeprom_test,
    SHELL_CMD_ARG(fill, NULL, "<offset> <len> <pattern>", cmd_eeprom_test_fill, 1, 3),
    SHELL_CMD_ARG(read, NULL, "<offset> <len>", cmd_eeprom_test_read, 1, 2),
    SHELL_CMD_ARG(verify, NULL, "<offset> <len> <pattern>", cmd_eeprom_test_verify, 1, 3),
    SHELL_CMD_ARG(size, NULL, NULL, cmd_eeprom_test_size, 1, 0),
    SHELL_CMD_ARG(info, NULL, NULL, cmd_eeprom_test_info, 1, 0),
    SHELL_SUBCMD_SET_END
);

SHELL_CMD_REGISTER(eeprom_test, &sub_eeprom_test, "EEPROM driver test commands", NULL);

void main(void)
{
    if (eeprom_dev == NULL) {
        LOG_ERR("EEPROM device is not available. Shell commands will not function.");
    } else if (!device_is_ready(eeprom_dev)) {
        LOG_ERR("EEPROM device %s is not ready. Shell commands will not function.", eeprom_dev->name);
    } else {
        LOG_INF("EEPROM shell test started. Device: %s", eeprom_dev->name);
    }
}
